/// Basic's class-level `is_Foo` flags.
#[allow(non_camel_case_types)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum Flag {
    Add = 0,
    AlgebraicNumber = 1,
    Atom = 2,
    Boolean = 3,
    Derivative = 4,
    Dummy = 5,
    Equality = 6,
    Float = 7,
    Function = 8,
    Indexed = 9,
    Integer = 10,
    MatAdd = 11,
    MatMul = 12,
    Matrix = 13,
    Mul = 14,
    Not = 15,
    Number = 16,
    NumberSymbol = 17,
    Order = 18,
    Piecewise = 19,
    Point = 20,
    Poly = 21,
    Pow = 22,
    Rational = 23,
    Relational = 24,
    Symbol = 25,
    Vector = 26,
    Wild = 27,
}

pub(crate) struct ClassInfo {
    /// `cls.__name__`.
    pub name: &'static str,
    /// `cls.class_key()[:2]` (the third entry is the name).
    pub class_key: (i32, i32),
    /// Bit `Tag as u8` is set when the class is a subclass of that tag.
    pub tags: u64,
    /// Bit `Flag as u8` is set when `cls.is_<Flag>` is true.
    pub flags: u64,
    /// `cls.is_number` when it is a plain class attribute (`None`: the
    /// `Expr.is_number` property, true when all args are numbers).
    pub is_number: Option<bool>,
    /// `cls.is_symbol`.
    pub is_symbol: bool,
    /// `default_assumptions`: facts it knows, which of those are true, and
    /// facts stored as `None` (a class attribute `is_foo = None`).
    pub default_known: u64,
    pub default_true: u64,
    pub default_none: u64,
    /// Facts with an `_eval_is_*` handler in `_prop_handler`.
    pub handlers: u64,
    /// For each handled fact, the SymPy method that handles it.
    pub handler_owners: &'static [(Fact, &'static str)],
    /// For each [`Method`], the class that defines it for this class
    /// (`cls.__mro__`'s first class with it in `__dict__`), or "" if none.
    pub method_owners: [&'static str; NUM_METHODS],
}

